    const myModel = new MyModel();
    myModel.users.push(new User({ name: 'John Doe', email: 'johndoe@example.com' }));
    myModel.products.push(new Product({ name: 'Product 1', description: 'This is a product' }));

    await myModel.save();

    return myModel;
  }
}
```

