$orderedSet = smart_sort_array($set, 'desc'); // Sort in descending order

print_r($orderedSet);
```

This will output the sorted set in either ascending or descending order based on the value of the `$order` parameter.

```javascript
function getOptionValues(dotNotationString, options) {
  const keys = dotNotationString.split(".");
  const values = [];

  options.forEach((option) => {
    let currentValue = option;

    for (const key of keys) {
      currentValue = currentValue[key];
    }

    if (currentValue === dotNotationString) {
      values.push(option);
    }
  });

  return values;
}
```

