Here's a decorator for Nest.js middleware that checks the NODE_ENV variable and returns `false` if it's not equal to 'true'. If NODE_ENV is equal to 'true', it calls the `next()` function.

```typescript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';

@Injectable()
export class EnvGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest();
    const nodeEnv = request.nodeEnv;

    if (nodeEnv === 'true') {
      return true;
    }

    return false;
  }
}
```

To use this decorator, you can apply it to your middleware functions like this:

```typescript
import { MiddlewareFunction, NestMiddleware } from '@nestjs/common';
import { EnvGuard } from './env-guard';

@NestMiddleware()
export class MyMiddleware implements MiddlewareFunction {
  constructor(private readonly envGuard: EnvGuard) {}

  async use(req: Request, res: Response, next: NextFunction) {
    if (await this.envGuard.canActivate(new ExecutionContext(req, res, next))) {
      next();
    } else {
      res.status(403).json({ error: 'Forbidden' });
    }
  }
}
```

