To create a simple toast notification using React context, follow these steps:

1. Create a ToastContext component that will act as the context provider.

```javascript
import React from 'react';

const ToastContext = React.createContext();

function ToastProvider(props) {
  const [toastMessage, setToastMessage] = React.useState(null);

  return (
    <ToastContext.Provider value={{ toastMessage, setToastMessage }}>
      {props.children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. Create a Toast component that will be used to display the toast message.

```javascript
import React from 'react';
import { useContext } from 'react';
import ToastContext from './ToastContext';

function Toast() {
  const { toastMessage } = useContext(ToastContext);

  if (!toastMessage) {
    return null;
  }

  return <div className="toast">{toastMessage}</div>;
}

export default Toast;
```

3. Use the ToastProvider component in your application and pass in your desired toast message.

```javascript
import React from 'react';
import ToastProvider from './ToastContext';

function App() {
  return (
    <ToastProvider>
      <Toast />
      {/* Your other components */}
    </ToastProvider>
  );
}

export default App;
```

4. Now you can display a toast message by calling the `setToastMessage` function provided by the ToastContext.

```javascript
import React from 'react';
import ToastProvider from './ToastContext';

function App() {
  const { toastMessage, setToastMessage } = useContext(ToastContext);

  // Display a toast message
  setToastMessage('This is a toast message!');

  // Your other components
}

export default App;
```

