class Book {
public:
    std::string title;
    std::string author;
    std::string summary;

    void setTitle(const std::string& title) { this->title = title; }
    void setAuthor(const std::string& author) { this->author = author; }
    void setSummary(const std::string& summary) { this->summary = summary; }

    std::string getTitle() const { return title; }
    std::string getAuthor() const { return author; }
    std::string getSummary() const { return summary; }

    bool equals(const Book& other) const {
        return title == other.title && author == other.author && summary == other.summary;
    }
};
