import re
from decimal import Decimal
from sqlite3 import connect

def english_number_to_words(num):
    if num < 0:
        return "negative " + english_number_to_words(-num)
    elif num == 0:
        return "zero"
    else:
        words = []
        while num > 0:
            words.append(str(num % 10))
            num //= 10
        return " ".join(reversed(words))

def scientific_notation_to_words(num):
    match = re.match(r'(\d+)\.?(\d*)e([+-]\d+)', str(num))
    if match:
        whole_number = int(match.group(1))
        fractional_part = match.group(2)
        exponent = int(match.group(3))
        return f"{english_number_to_words(whole_number)} point {fractional_part} times ten raised to the power of {exponent}"
    else:
        return "invalid scientific notation"

def language_conversion(num, lang):
    if lang == "fr":
        return english_number_to_words(num)
    elif lang == "es":
        return english_number_to_words(num)
    elif lang == "de":
        return english_number_to_words(num)
    else:
        return "invalid language"

def sql_format_to_words(num):
