```typescript
import { useCombobox } from 'downshift';
import { useState } from 'react';

interface Email {
  id: number;
  email: string;
}

const Emails = () => {
  const [emails, setEmails] = useState([]);

  const searchEmails = async (prefix: string) => {
    // Implement your API call or logic to fetch emails based on prefix
    // For this example, we'll just simulate some data
    const filteredEmails = emails.filter((email) =>
      email.email.toLowerCase().startsWith(prefix.toLowerCase())
    );
    return filteredEmails;
  };

  const {
    isOpen,
    selectedItem,
    getMenuProps,
    getInputProps,
    getComboboxProps,
  } = useCombobox({
    items: emails,
    getItemToString: (item) => item.email,
    onSelect: (selectedItem) => console.log('Selected item:', selectedItem),
    onInputValueChange: async (inputValue) => {
      const filteredEmails = await searchEmails(inputValue);
      setEmails(filteredEmails);
    },
  });

  return (
    <div {...getComboboxProps()}>
      <input {...getInputProps()} placeholder="Search emails" />
      <button {...getMenuProps()}>Open menu</button>
      {isOpen && (
        <ul {...getMenuProps()}>
          {emails.map((email) => (
            <li key={email.id} {...getMenuItemProps({ item: email })}>
              {email.email}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Emails;
```

