Here's an example implementation using the Accord.NET library to perform text classification using Naive Bayes:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using Accord.MachineLearning;
using Accord.MachineLearning.Bayesian;
using Accord.Text;

class Program
{
    static void Main(string[] args)
    {
        // Load the dataset
        var dataset = new List<(string sentence, string label)>
        {
            ("Sports game was exciting", "Sports"),
            ("Politician made a controversial statement", "Politics"),
            ("Celebrity attended a red carpet event", "Entertainment"),
            ("Sports game was boring", "Sports"),
            ("Politician proposed a new law", "Politics"),
            ("Celebrity released a new album", "Entertainment"),
        };

        // Create a Naive Bayes classifier
        var naiveBayes = new NaiveBayes();

        // Preprocess the data
        var vectorizer = new CountVectorizer();
        var preprocessedDataset = vectorizer.Transform(dataset);

        // Train the model
        naiveBayes.Train(preprocessedDataset);

        // Classify a new sentence
        var newSentence = "The sports game was exciting";
        var prediction = naiveBayes.Predict(newSentence);

        Console.WriteLine($"Predicted label: {prediction}");
    }
}
```

