Here's a Go program that identifies if a given sentence contains a double negative using the specified approach:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	negativeWords := []string{"not", "never", "no", "none"}

	// Split the sentence into words
	words := strings.Split(sentence, " ")

	// Check if any negative words are present
	for _, word := range words {
		if containsNegativeWord(word, negativeWords) {
			return true
		}
	}

	// Check for the "not" followed by a negative word
	prevWord := ""
	for _, word := range words {
		if prevWord == "not" && containsNegativeWord(word, negativeWords) {
			return true
		}
		prevWord = word
	}

	fmt.Println("The sentence does not contain a double negative.")
}

func containsNegativeWord(word string, negativeWords []string) bool {
	for _, negWord := range negativeWords {
		if strings.ToLower(word) == negWord {
			return true
		}
	}
	return false
}
```

This program will output `The sentence does not contain a double negative.` for the given example sentence. You can modify the `negativeWords` slice to include more negative words or customize the logic to suit your needs.

